parameters.jsCode:
// Safe parse of the AI reply. If the AI returns anything that is not
// clean JSON, fall back to 'unclassified' instead of breaking the flow —
// the email is still logged, and the owner reads it directly.
const email = $('Normalise Email').first().json;
const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
const fallback = { category: 'unclassified', urgency: 'normal', summary: 'AI output could not be parsed — read the email directly.', draft_reply: '' };
if (!parsed || typeof parsed !== 'object') parsed = fallback;
const categories = ['lead', 'support', 'billing', 'spam-or-other'];
return [{ json: {
  ...email,
  category: categories.includes(parsed.category) ? parsed.category : 'unclassified',
  urgency: parsed.urgency === 'high' ? 'high' : 'normal',
  summary: (parsed.summary || fallback.summary).toString(),
  draft_reply: (parsed.draft_reply || '').toString()
} }];

